// @vitest-environment node
import { describe, expect, it, vi } from 'vitest';

vi.mock('./wasm', async () => {
    const { readFileSync: read } = await import('node:fs');
    const dir = new URL('../wasm-pkg/', import.meta.url);
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore — generated by scripts/build-wasm.sh (wasm-bindgen)
    const glue = await import('../wasm-pkg/anonymiser_wasm');
    glue.initSync({ module: read(new URL('anonymiser_wasm_bg.wasm', dir)) });
    return { ...glue, ensureWasm: async () => {} };
});

import { atRiskRows, planAnonymity } from './anonymity-plan';

const HEADERS = ['id', 'dob', 'city'];
const ROWS = [
    [1, '1980-01-01', 'Bristol'],
    [2, '1980-06-30', 'Bristol'],
    [3, '1980-12-11', 'Bristol'],
    [4, '1990-02-02', 'Leeds'],
    [5, '1990-03-03', 'Bristol'],
    [6, '1990-04-04', 'Bristol'],
];

describe('atRiskRows (real core)', () => {
    it('lists the rows in groups smaller than k among the post-policy values', async () => {
        const risky = await atRiskRows(ROWS, HEADERS, [], { 1: { type: 'year' } }, {}, [1, 2], 3);
        expect(risky.map((r) => r.row)).toEqual([3, 4, 5]);
        expect(risky[0].values).toEqual(['1990', 'Leeds']);
    });

    it('is empty when everything reaches k', async () => {
        expect(await atRiskRows(ROWS, HEADERS, [], { 1: { type: 'redact' }, 2: { type: 'redact' } }, {}, [1, 2], 3)).toEqual([]);
    });
});

describe('planAnonymity (real core)', () => {
    it('finds year + keeping city with a 50% budget, and drops city at 0%', async () => {
        const loose = await planAnonymity(ROWS, HEADERS, [], {}, [1, 2], ['date', 'other'], 3, 0.5);
        expect(loose.achievable).toBe(true);
        expect(loose.steps.map((s) => s.policy.type)).toEqual(['year']);
        expect(loose.rowsBelowK).toBe(3);
        const strict = await planAnonymity(ROWS, HEADERS, [], {}, [1, 2], ['date', 'other'], 3, 0);
        expect(strict.achievable).toBe(true);
        expect(strict.rowsBelowK).toBe(0);
        expect(strict.steps.map((s) => s.name)).toContain('city');
    });

    it('is deterministic', async () => {
        const a = await planAnonymity(ROWS, HEADERS, [], {}, [1, 2], ['date', 'other'], 3, 0.1);
        const b = await planAnonymity(ROWS, HEADERS, [], {}, [1, 2], ['date', 'other'], 3, 0.1);
        expect(a).toEqual(b);
    });
});
